21	/// A pattern rule: regex pattern string + the classification it triggers.
22	#[derive(Debug, Clone)]
23	struct PatternRule {
24	    /// Human-readable name for logging.
25	    name: &'static str,
26	    /// The classification tier this pattern triggers.
27	    tier: Classification,
28	    /// A simple substring or pattern to match (case-insensitive).
29	    /// For this implementation we use substring matching to avoid a regex
30	    /// dependency; a production system would use `regex`.
31	    pattern: &'static str,
32	}
33	
