83	/// Classifies clipboard text content into a sensitivity tier.
84	#[derive(Debug)]
85	pub struct ContentClassifier;
86	
87	impl ContentClassifier {
88	    /// Classifies the given text and returns the highest matching tier.
89	    ///
90	    /// Returns `Classification::T1` (Public) if no sensitive patterns match.
91	    #[must_use]
92	    pub fn classify(text: &str) -> Classification {
93	        let lower = text.to_lowercase();
94	
95	        // Check structured data patterns first (highest sensitivity).
96	        if contains_ssn_pattern(text) {
97	            debug!("clipboard classified as T4: SSN pattern detected");
98	            return Classification::T4;
99	        }
100	        if contains_credit_card_pattern(text) {
101	            debug!("clipboard classified as T4: credit card pattern detected");
102	            return Classification::T4;
103	        }
104	
105	        // Check keyword rules in priority order.
106	        for rule in DEFAULT_RULES {
107	            // Skip the structured-data sentinel patterns.
108	            if rule.pattern == "SSN_PATTERN" || rule.pattern == "CC_PATTERN" {
109	                continue;
110	            }
111	            if lower.contains(rule.pattern) {
112	                debug!(
113	                    rule = rule.name,
114	                    tier = ?rule.tier,
115	                    "clipboard classified by keyword match"
116	                );
117	                return rule.tier;
118	            }
119	        }
120	
121	        Classification::T1
122	    }
123	}
