125	/// Returns `true` if the text contains a pattern matching SSN format
126	/// (3 digits, separator, 2 digits, separator, 4 digits).
127	fn contains_ssn_pattern(text: &str) -> bool {
128	    // Simple state machine: look for XXX-XX-XXXX or XXX XX XXXX patterns.
129	    let chars: Vec<char> = text.chars().collect();
130	    if chars.len() < 11 {
131	        return false;
132	    }
133	    for window in chars.windows(11) {
134	        let sep = window[3];
135	        if (sep == '-' || sep == ' ')
136	            && window[6] == sep
137	            && window[0..3].iter().all(|c| c.is_ascii_digit())
138	            && window[4..6].iter().all(|c| c.is_ascii_digit())
139	            && window[7..11].iter().all(|c| c.is_ascii_digit())
140	        {
141	            return true;
142	        }
143	    }
144	    false
145	}
146	
147	/// Returns `true` if the text contains a pattern resembling a credit card
148	/// number (16 digits, optionally separated by dashes or spaces in groups of 4).
149	fn contains_credit_card_pattern(text: &str) -> bool {
150	    // Extract only digits from the text and check for 16-digit sequences.
151	    // Also check for formatted patterns: XXXX-XXXX-XXXX-XXXX
152	    let chars: Vec<char> = text.chars().collect();
153	
154	    // Check formatted pattern: 4 digits, sep, 4 digits, sep, 4 digits, sep, 4 digits
155	    if chars.len() >= 19 {
156	        for window in chars.windows(19) {
157	            let sep = window[4];
158	            if (sep == '-' || sep == ' ')
159	                && window[9] == sep
160	                && window[14] == sep
161	                && window[0..4].iter().all(|c| c.is_ascii_digit())
162	                && window[5..9].iter().all(|c| c.is_ascii_digit())
163	                && window[10..14].iter().all(|c| c.is_ascii_digit())
164	                && window[15..19].iter().all(|c| c.is_ascii_digit())
165	            {
166	                return true;
167	            }
168	        }
169	    }
170	
171	    // Check raw 16-digit sequence.
172	    let mut consecutive_digits = 0u32;
173	    for ch in text.chars() {
174	        if ch.is_ascii_digit() {
175	            consecutive_digits += 1;
176	            if consecutive_digits >= 16 {
177	                return true;
178	            }
179	        } else {
180	            consecutive_digits = 0;
181	        }
182	    }
183	
184	    false
185	}
