420	    /// Reads the current clipboard text content via Windows API.
421	    ///
422	    /// Returns `None` if the clipboard does not contain `CF_UNICODETEXT` data
423	    /// or if the clipboard cannot be opened.
424	    pub fn read_clipboard_text() -> Option<String> {
425	        use windows::Win32::Foundation::HGLOBAL;
426	        use windows::Win32::System::DataExchange::{
427	            CloseClipboard, GetClipboardData, OpenClipboard,
428	        };
429	        use windows::Win32::System::Memory::{GlobalLock, GlobalUnlock};
430	
431	        // CF_UNICODETEXT = 13
432	        const CF_UNICODETEXT: u32 = 13;
433	
434	        // SAFETY: OpenClipboard(None) opens the clipboard for the current task.
435	        if unsafe { OpenClipboard(None) }.is_err() {
436	            return None;
437	        }
438	
439	        let result = unsafe {
440	            let handle = GetClipboardData(CF_UNICODETEXT);
441	            match handle {
442	                Ok(h) => {
443	                    // SAFETY: clipboard data handle is valid while clipboard
444	                    // is open; HGLOBAL wraps the same pointer type.
445	                    let hglobal = HGLOBAL(h.0);
446	                    let ptr = GlobalLock(hglobal);
447	                    if ptr.is_null() {
448	                        None
449	                    } else {
450	                        let text = read_wide_string(ptr as *const u16);
451	                        let _ = GlobalUnlock(hglobal);
452	                        text
453	                    }
454	                }
455	                Err(_) => None,
456	            }
457	        };
458	
459	        // SAFETY: clipboard was opened successfully above.
460	        let _ = unsafe { CloseClipboard() };
461	
462	        result
463	    }
464	}
