484	/// Window procedure for the hidden clipboard listener window.
485	///
486	/// Handles `WM_DESTROY` (triggers `PostQuitMessage`) and forwards everything
487	/// else to `DefWindowProcW`.
488	#[cfg(windows)]
489	extern "system" fn wndproc_callback(
490	    hwnd: HWND,
491	    msg: u32,
492	    wparam: WPARAM,
493	    lparam: LPARAM,
494	) -> windows::Win32::Foundation::LRESULT {
495	    // SAFETY: DefWindowProcW is always safe to call with valid parameters.
496	    match msg {
497	        windows::Win32::UI::WindowsAndMessaging::WM_DESTROY => {
498	            unsafe { PostQuitMessage(0) };
499	            windows::Win32::Foundation::LRESULT(0)
500	        }
501	        _ => unsafe { DefWindowProcW(hwnd, msg, wparam, lparam) },
502	    }
503	}
