505	/// `WH_GETMESSAGE` hook procedure.
506	///
507	/// Fires for every `GetMessage` / `PeekMessage` call on the thread that installed
508	/// the hook.  For `WH_GETMESSAGE`, the wparam is the actual message ID and lparam
509	/// is a pointer to the `MSG` struct.
510	///
511	/// On `WM_PASTE` (0x0302) it reads the clipboard, classifies the text,
512	/// and emits a `ClipboardEvent` through the running listener.
513	///
514	/// This function runs on the clipboard-listener thread — it is safe to call
515	/// `OpenClipboard` / `GetClipboardData` here because there is no concurrent
516	/// clipboard access from this thread.
517	#[cfg(windows)]
518	unsafe extern "system" fn hook_procedure(_code: i32, wparam: WPARAM, lparam: LPARAM) -> LRESULT {
519	    // For WH_GETMESSAGE: wparam is the message ID (cast to raw value).
520	    let msg = wparam.0 as u32;
521	
522	    if msg == WM_PASTE {
523	        if let Some(listener) = HOOK_LISTENER.get() {
524	            if let Some(text) = ClipboardListener::read_clipboard_text() {
525	                listener.process_clipboard_text(&text);
526	            }
527	        }
528	    }
529	    // Always call the next hook in the chain (there is none at the end, so pass None).
530	    // SAFETY: wparam and lparam are passed through unchanged — we only observe the message.
531	    CallNextHookEx(None, _code, wparam, lparam)
532	}
