534	/// Reads a null-terminated UTF-16 string from a pointer.
535	///
536	/// Returns `None` if the pointer is null.
537	fn read_wide_string(ptr: *const u16) -> Option<String> {
538	    if ptr.is_null() {
539	        return None;
540	    }
541	    let mut len = 0usize;
542	    while unsafe { *ptr.add(len) } != 0 {
543	        len += 1;
544	        if len > 1_000_000 {
545	            // Sanity limit: 1M characters.
546	            break;
547	        }
548	    }
549	    let slice = unsafe { std::slice::from_raw_parts(ptr, len) };
550	    String::from_utf16(slice).ok()
551	}
