553	/// Truncates text to `max_len` characters, appending "..." if truncated.
554	fn truncate_preview(text: &str, max_len: usize) -> String {
555	    if text.len() <= max_len {
556	        text.to_string()
557	    } else {
558	        let boundary = text
559	            .char_indices()
560	            .take_while(|(i, _)| *i < max_len.saturating_sub(3))
561	            .last()
562	            .map(|(i, c)| i + c.len_utf8())
563	            .unwrap_or(0);
564	        format!("{}...", &text[..boundary])
565	    }
566	}
