310	    pub fn stop(&self) {
311	        if self.stop_flag.swap(true, Ordering::SeqCst) {
312	            return; // already stopped
313	        }
314	
315	        // Signal the message loop to exit via PostThreadMessageW.
316	        // SAFETY: PostThreadMessageW with WM_QUIT is safe — it posts a quit
317	        // message that causes GetMessageW to return 0, cleanly exiting the loop.
318	        let thread_id = unsafe { windows::Win32::System::Threading::GetCurrentThreadId() };
319	        let _ =
320	            unsafe { PostThreadMessageW(thread_id, WM_QUIT, WPARAM::default(), LPARAM::default()) };
321	
322	        // Wait for the thread to finish.
323	        let mut handle_guard = self.thread_handle.lock();
324	        let handle = handle_guard.take();
325	        drop(handle_guard);
326	        if let Some(handle) = handle {
327	            let _ = handle.join();
328	        }
329	
330	        // Unhook explicitly if the thread didn't do it.
331	        let mut hhook_guard = self.hhook.lock();
332	        let hhook = hhook_guard.take();
333	        drop(hhook_guard);
334	        if let Some(SendableHhook(hhook)) = hhook {
335	            let _ = unsafe { UnhookWindowsHookEx(hhook) };
336	        }
337	
338	        info!(session_id = self.session_id, "clipboard listener stopped");
339	    }
